public class Main {
    int repeatedStringMatch(String a, String b) {
        StringBuilder repeated = new StringBuilder(a);
        int count = 1;
        while (repeated.length() < b.length()) {
            repeated.append(a);                                        // grow the repeated string one copy at a time
            count++;
        }
        if (repeated.toString().contains(b)) return count;
        repeated.append(a);                                             // one more copy, in case b spans a boundary
        count++;
        if (repeated.toString().contains(b)) return count;
        return -1;
    }

    public static void main(String[] args) {
        String a = "abcd";
        String b = "cdabcdab";
        Main solution = new Main();
        System.out.println(solution.repeatedStringMatch(a, b));
    }
}

