int repeatedStringMatch(string a, string b) {
    string repeated = a;
    int count = 1;
    while (repeated.size() < b.size()) {
        repeated += a;                                               // grow the repeated string one copy at a time
        count++;
    }
    if (repeated.find(b) != string::npos) return count;
    repeated += a;                                                     // one more copy, in case b spans a boundary
    count++;
    if (repeated.find(b) != string::npos) return count;
    return -1;
}

