def repeated_string_match(a, b):
    min_count = -(-len(b) // len(a))                        # ceiling division: minimum repeats to reach b's length
    for count in (min_count, min_count + 1):                    # only these two candidates can ever work
        if b in a * count:
            return count
    return -1


if __name__ == "__main__":
    a = "abcd"
    b = "cdabcdab"
    print(repeated_string_match(a, b))

