public class Main {
    int repeatedStringMatch(String a, String b) {
        int minCount = (b.length() + a.length() - 1) / a.length();   // ceiling division: minimum repeats to reach b's length
        for (int count = minCount; count <= minCount + 1; count++) {    // only these two candidates can ever work
            StringBuilder repeated = new StringBuilder();
            for (int i = 0; i < count; i++) repeated.append(a);
            if (repeated.toString().contains(b)) return count;
        }
        return -1;
    }

    public static void main(String[] args) {
        String a = "abcd";
        String b = "cdabcdab";
        Main solution = new Main();
        System.out.println(solution.repeatedStringMatch(a, b));
    }
}

